      #pendulum {
        position: absolute;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
      }
    </style>
  </head>
  <body>
    <canvas id="pendulum" width="400" height="400"></canvas>
    <input type="number" id="angle" placeholder="Initial angle (degrees)">
    <button id="release">Release</button>
    <script>
      let canvas = document.getElementById('pendulum');
      let ctx = canvas.getContext('2d');
      let canvasWidth = canvas.width;
      let canvasHeight = canvas.height;
      let gravity = 0.98; // adjusts the falling speed
      let angle = 0; // initial angle
      let velocity = 0; // initial velocity
      let time = 0; // time
      let gameOver = false;

      function init() {
        ctx.fillStyle = 'black';
        ctx.fillRect(0, 0, canvasWidth, canvasHeight);
      }

      function drawPendulum(angle) {
        let pendulumLength = 100;
        let x = canvasWidth / 2;
        let y = canvasHeight / 2;
        let endX = x + Math.sin(angle) * pendulumLength;
        let endY = y - Math.cos(angle) * pendulumLength;

        ctx.beginPath();
        ctx.lineWidth = 2;
        ctx.strokeStyle = 'white';
        ctx.moveTo(x, y);
        ctx.lineTo(endX, endY);
        ctx.stroke();

        ctx.beginPath();
        ctx.arc(endX, endY, 4, 0, 2 * Math.PI);
        ctx.fillStyle = 'white';
        ctx.fill();
      }

      function updatePendulum() {
        if (!gameOver) {
          time += gravity;
          velocity = Math.sin(angle);
          angle -= velocity;
          if (Math.abs(angle) > Math.PI/2) {
            gameOver = true;
          }
          drawPendulum(angle);
          requestAnimationFrame(updatePendulum);
        }
      }

      document.getElementById('release').addEventListener('click', () => {
        angle = document.getElementById('angle').value * Math.PI / 180;
        velocity = 0;
        time = 0;
        gameOver = false;
        init();
        updatePendulum();
      });

      document.getElementById('angle').addEventListener('input', () => {
        if (gameOver) {
          angle = document.getElementById('angle').value * Math.PI / 180;
          velocity = 0;
          time = 0;
          gameOver = false;
          init();
          updatePendulum();
        }
      });

      init();
    </script>
  </body>
