	}

	ec2Svc := ec2.New(sess)

	backupTypes := map[string]int{
		"monthly": 14,
		"daily":   10,
		"weekly":  4,
		"yearly":  1,
	}

	err = deleteSnapshots(ec2Svc, backupTypes)
	if err != nil {
		log.Fatal(err)
	}
}

func deleteSnapshots(ec2Svc *ec2.EC2, backupTypes map[string]int) error {
	ctx := context.Background()

	// Get all EBS Snapshots
	snapshots, err := ec2Svc.DescribeSnapshots(&ec2.DescribeSnapshotsInput{}).SnapshotIdsSnapshotList()
	if err != nil {
		return err
	}

	// Group snapshots by backup_type
_BUCKET := make(map[string][]*ec2.Snapshot)
	for _, snapshot := range snapshots {
		tag, ok := getTag(snapshot.Tags, "backup_type")
		if !ok {
			continue
		}
		if _, ok := _BUCKET[tag]; !ok {
			_BUCKET[tag] = []*ec2.Snapshot{}
		}
		_BUCKET[tag] = append(_BUCKET[tag], snapshot)
	}

	// Delete snapshots for each backup_type
	for backupType, numToDelete := range backupTypes {
		if len(_BUCKET[backupType]) > numToDelete {
			snapshotsToKeep := _BUCKET[backupType][:numToDelete]
			for _, snapshot := range _BUCKET[backupType][numToDelete:] {
				fmt.Printf("Deleting snapshot %s (backup_type: %s)\n", *snapshot.SnapshotId, backupType)
				_, err = ec2Svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{
					SnapshotId: aws.String(*snapshot.SnapshotId),
				})
				if err != nil {
					return err
				}
			}
		}
	}

	return nil
}

func getTag(tags []*ec2.Tag, key string) (string, bool) {
	for _, tag := range tags {
		if *tag.Key == key {
			return *tag.Value, true
		}
	}
	return "", false
}
